###############################################################
# 6. HELPER FUNCTIONS
###############################################################

safe_mean <- function(x) {

    x <- x[
        is.finite(x)
    ]

    if (length(x) == 0) {
        return(NA_real_)
    }

    mean(x)

}


safe_sd <- function(x) {

    x <- x[
        is.finite(x)
    ]

    if (length(x) < 2) {
        return(NA_real_)
    }

    sd(x)

}


safe_sharpe <- function(x) {

    x <- x[
        is.finite(x)
    ]

    if (length(x) < 2) {
        return(NA_real_)
    }

    s <- sd(x)

    if (!is.finite(s) || s <= 0) {
        return(NA_real_)
    }

    mean(x) / s

}


safe_cumulative_return <- function(x) {

    x <- x[
        is.finite(x)
    ]

    if (length(x) == 0) {
        return(NA_real_)
    }

    prod(
        1 + x
    ) - 1

}


safe_max_drawdown <- function(x) {

    x <- x[
        is.finite(x)
    ]

    if (length(x) == 0) {
        return(NA_real_)
    }

    wealth <- cumprod(
        1 + x
    )

    running_max <- cummax(
        wealth
    )

    drawdown <-
        wealth / running_max - 1

    min(
        drawdown
    )

}


safe_hit_rate <- function(
    expected,
    realized
) {

    keep <-
        is.finite(expected) &
        is.finite(realized)

    expected <- expected[keep]

    realized <- realized[keep]

    if (length(expected) == 0) {
        return(NA_real_)
    }

    mean(
        sign(expected) ==
        sign(realized)
    )

}


###############################################################
# 7. MODEL-LEVEL PERFORMANCE
###############################################################

financial_model_summary <-
    financial_decision_detail %>%
    dplyr::group_by(
        Model
    ) %>%
    dplyr::summarise(

        N =
            sum(
                is.finite(
                    NetRealizedReturn
                )
            ),

        MeanExpectedReturn =
            safe_mean(
                SelectedExpectedReturn
            ),

        MeanRealizedReturn =
            safe_mean(
                SelectedRealizedReturn
            ),

        MeanNetReturn =
            safe_mean(
                NetRealizedReturn
            ),

        SDNetReturn =
            safe_sd(
                NetRealizedReturn
            ),

        SharpeLike =
            safe_sharpe(
                NetRealizedReturn
            ),

        CumulativeGrossReturn =
            safe_cumulative_return(
                SelectedRealizedReturn
            ),

        CumulativeNetReturn =
            safe_cumulative_return(
                NetRealizedReturn
            ),

        MaximumDrawdown =
            safe_max_drawdown(
                NetRealizedReturn
            ),

        SwitchingRate =
            safe_mean(
                PortfolioSwitch
            ),

        NumberOfSwitches =
            sum(
                PortfolioSwitch,
                na.rm = TRUE
            ),

        DirectionalHitRate =
            safe_hit_rate(
                SelectedExpectedReturn,
                SelectedRealizedReturn
            ),

        ShortSelectionRate =
            safe_mean(
                SelectedPortfolio ==
                "Short"
            ),

        IntermediateSelectionRate =
            safe_mean(
                SelectedPortfolio ==
                "Intermediate"
            ),

        LongSelectionRate =
            safe_mean(
                SelectedPortfolio ==
                "Long"
            ),

        MeanTransactionCost =
            safe_mean(
                TransactionCost
            ),

        TotalTransactionCost =
            sum(
                TransactionCost,
                na.rm = TRUE
            ),

        .groups = "drop"

    )


###############################################################
# 8. SORT MODELS BY NET PERFORMANCE
###############################################################

