    dplyr::arrange(
        dplyr::desc(
            CumulativeNetReturn
        )
    )


###############################################################
# 9. PAIRWISE RETURN DIFFERENCES
###############################################################

model_names <-
    unique(
        financial_decision_detail$Model
    )


if (
    length(model_names) < 2
) {

    stop(
        "At least two models are required for pairwise comparison."
    )

}


pair_list <- list()

pair_counter <- 0


for (i in seq_len(length(model_names) - 1)) {

    for (
        j in (i + 1):length(model_names)
    ) {

        model_1 <-
            model_names[i]

        model_2 <-
            model_names[j]


        data_1 <-
            financial_decision_detail %>%
            dplyr::filter(
                Model == model_1
            ) %>%
            dplyr::select(
                TestIndex,
                Return_1 =
                    NetRealizedReturn
            )


        data_2 <-
            financial_decision_detail %>%
            dplyr::filter(
                Model == model_2
            ) %>%
            dplyr::select(
                TestIndex,
                Return_2 =
                    NetRealizedReturn
            )


        comparison <-
            dplyr::inner_join(
                data_1,
                data_2,
                by = "TestIndex"
            )


        comparison <- comparison %>%
            dplyr::filter(
                is.finite(
                    Return_1
                ) &
                is.finite(
                    Return_2
                )
            )


        if (
            nrow(comparison) == 0
        ) {

            next

        }


        comparison$Difference <-
            comparison$Return_1 -
            comparison$Return_2


        pair_counter <-
            pair_counter + 1


        pair_list[[pair_counter]] <-
            comparison %>%
            dplyr::mutate(
                Model_1 =
                    model_1,
                Model_2 =
                    model_2
            ) %>%
            dplyr::select(
                Model_1,
                Model_2,
                TestIndex,
                Return_1,
                Return_2,
                Difference
            )

    }

}


financial_return_differences <-
    dplyr::bind_rows(
        pair_list
    )


###############################################################
# 10. DIEBOLD--MARIANO TEST
###############################################################

dm_results <- list()

dm_counter <- 0


pair_keys <-
    unique(
        financial_return_differences %>%
            dplyr::select(
                Model_1,
                Model_2
            )
    )


for (
    i in seq_len(
        nrow(pair_keys)
    )
) {

    model_1 <-
        pair_keys$Model_1[i]

    model_2 <-
        pair_keys$Model_2[i]


    comparison <-
        financial_return_differences %>%
        dplyr::filter(
            Model_1 == model_1,
            Model_2 == model_2
        )


    x <-
        comparison$Return_1

    y <-
        comparison$Return_2


    keep <-
        is.finite(x) &
        is.finite(y)


    x <- x[keep]

    y <- y[keep]


    if (
        length(x) < 10
    ) {

        next

    }


    dm_object <- tryCatch(

        forecast::dm.test(
            e1 = x,
            e2 = y,
            alternative = "two.sided",
            h = 1,
            power = 2
        ),

        error = function(e) {
            NULL
        }

    )


    dm_counter <-
        dm_counter + 1


    if (
        is.null(dm_object)
    ) {

        dm_results[[dm_counter]] <-
            data.frame(
                Model_1 = model_1,
                Model_2 = model_2,
                N = length(x),
                DM = NA_real_,
                p_value = NA_real_,
                Alternative = "two.sided",
                stringsAsFactors = FALSE
            )

    } else {

        dm_results[[dm_counter]] <-
            data.frame(
                Model_1 = model_1,
                Model_2 = model_2,
                N = length(x),
                DM =
                    as.numeric(
                        dm_object$statistic
                    ),
                p_value =
                    as.numeric(
                        dm_object$p.value
                    ),
                Alternative =
                    dm_object$alternative,
                stringsAsFactors = FALSE
            )

    }

}


financial_DM_tests <-
    dplyr::bind_rows(
        dm_results
    )


###############################################################
# 11. PAIRED BOOTSTRAP
###############################################################

bootstrap_difference <- function(
    x,
    y,
    B = 5000,
    seed = 20260914
) {

    keep <-
        is.finite(x) &
        is.finite(y)

    x <- x[keep]

    y <- y[keep]


    n <- length(x)


    if (n < 2) {

        return(
            data.frame(
                N = n,
                MeanDifference = NA_real_,
                CI_Lower = NA_real_,
                CI_Upper = NA_real_,
                P_Value = NA_real_
            )
        )

    }


    difference <-
        x - y


    observed <-
        mean(
            difference
        )


    set.seed(
        seed
    )


    bootstrap_values <-
        numeric(B)


    for (
        b in seq_len(B)
    ) {

        index <-
            sample.int(
                n,
                size = n,
                replace = TRUE
            )

        bootstrap_values[b] <-
            mean(
                difference[index]
            )

    }


    ci <-
        stats::quantile(
            bootstrap_values,
            probs = c(
                0.025,
                0.975
            ),
            na.rm = TRUE
        )


    p_value <-
        2 *
        min(
            mean(
                bootstrap_values <= 0
            ),
            mean(
                bootstrap_values >= 0
            )
        )


    data.frame(

        N = n,

        MeanDifference =
            observed,

        CI_Lower =
            as.numeric(
                ci[1]
            ),

        CI_Upper =
            as.numeric(
                ci[2]
            ),

        P_Value =
            p_value

    )

}


###############################################################
# 12. BOOTSTRAP MODEL COMPARISONS
###############################################################

bootstrap_results <- list()

bootstrap_counter <- 0


for (
    i in seq_len(
        nrow(pair_keys)
    )
) {

    model_1 <-
        pair_keys$Model_1[i]

    model_2 <-
        pair_keys$Model_2[i]


    comparison <-
        financial_return_differences %>%
        dplyr::filter(
            Model_1 == model_1,
            Model_2 == model_2
        )


    result <-
        bootstrap_difference(
            comparison$Return_1,
            comparison$Return_2,
            B = 5000,
            seed =
                20260914 + i
        )


    bootstrap_counter <-
        bootstrap_counter + 1


    result$Model_1 <-
        model_1

    result$Model_2 <-
        model_2


    bootstrap_results[[bootstrap_counter]] <-
        result %>%
        dplyr::select(
            Model_1,
            Model_2,
            dplyr::everything()
        )

}


financial_bootstrap_CI <-
    dplyr::bind_rows(
        bootstrap_results
    )


###############################################################
# 13. COMBINE STATISTICAL TEST RESULTS
###############################################################

financial_statistical_comparison <-
    dplyr::left_join(
        financial_DM_tests,
        financial_bootstrap_CI,
        by = c(
            "Model_1",
            "Model_2",
            "N"
        )
    )


###############################################################
# 14. PAIRED RETURN SUMMARY
###############################################################

paired_return_summary <-
    financial_return_differences %>%
    dplyr::group_by(
        Model_1,
        Model_2
    ) %>%
    dplyr::summarise(

        N =
            dplyr::n(),

        MeanDifference =
            mean(
                Difference,
                na.rm = TRUE
            ),

        MedianDifference =
            median(
                Difference,
                na.rm = TRUE
            ),

        SDDifference =
            sd(
                Difference,
                na.rm = TRUE
            ),

        PositiveDifferenceRate =
            mean(
                Difference > 0,
                na.rm = TRUE
            ),

        .groups = "drop"

    )


###############################################################
# 15. MAXIMUM DRAWDOWN BY MODEL
###############################################################

drawdown_summary <-
    financial_decision_detail %>%
    dplyr::group_by(
        Model
    ) %>%
    dplyr::arrange(
        TestIndex,
        .by_group = TRUE
    ) %>%
    dplyr::mutate(

        Wealth =
            cumprod(
                1 +
                dplyr::coalesce(
                    NetRealizedReturn,
                    0
                )
            ),

        RunningMaximum =
            cummax(
                Wealth
            ),

        Drawdown =
            Wealth /
            RunningMaximum -
            1

    ) %>%
    dplyr::summarise(

        MaximumDrawdown =
            min(
                Drawdown,
                na.rm = TRUE
            ),

        .groups = "drop"

    )


###############################################################
# 16. ADD DRAWDOWN TO SUMMARY
###############################################################

financial_model_summary <-
    financial_model_summary %>%
    dplyr::select(
        -dplyr::any_of(
            "MaximumDrawdown"
        )
    ) %>%
    dplyr::left_join(
        drawdown_summary,
        by = "Model"
    ) %>%
    dplyr::arrange(
        dplyr::desc(
            CumulativeNetReturn
        )
    )


###############################################################
# 17. RANKING
###############################################################

financial_model_summary <-
    financial_model_summary %>%
    dplyr::mutate(

        Rank_CumulativeReturn =
            rank(
                -CumulativeNetReturn,
                ties.method = "min"
            ),

        Rank_Sharpe =
            rank(
                -SharpeLike,
                ties.method = "min"
            ),

        Rank_Drawdown =
            rank(
                -MaximumDrawdown,
                ties.method = "min"
            )

    )


###############################################################
# 18. OUTPUT DETAIL
